        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the incorrect type assignment for the `destStride` variable, which was originally set as `uint`. This could lead to incorrect calculations or handling of the pixel data, especially in cases where negative values or specific conditions in pixel processing were expected. Changing it to `int` ensures proper handling of all potential values for stride calculations, particularly when addressing the inversion of packed image data.

        Commit message:
        st/mesa: fix readpixels regression with MESA_pack_invert
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Fixes an error introduced in commit 3948cd37973696dc319170877382676809659465.

Reported-by: Marek Olšák <marek.olsak@amd.com>
Reviewed-by: Brian Paul <brianp@vmware.com>
Reviewed-by: Marek Olšák <marek.olsak@amd.com>  

        Patch:
          */
 static void
 st_ReadPixels(struct gl_context *ctx, GLint x, GLint y,
               GLsizei width, GLsizei height,
               GLenum format, GLenum type,
               const struct gl_pixelstore_attrib *pack,
               void *pixels)
 {
    struct st_context *st = st_context(ctx);
    struct gl_renderbuffer *rb =
          _mesa_get_read_renderbuffer_for_format(ctx, format);
    struct st_renderbuffer *strb = st_renderbuffer(rb);
    struct pipe_context *pipe = st->pipe;
    struct pipe_screen *screen = pipe->screen;
    struct pipe_resource *src;
    struct pipe_resource *dst = NULL;
    enum pipe_format dst_format, src_format;
    unsigned bind = PIPE_BIND_TRANSFER_READ;
    struct pipe_transfer *tex_xfer;
    ubyte *map = NULL;
    bool window;

    /* Validate state (to be sure we have up-to-date framebuffer surfaces)
     * and flush the bitmap cache prior to reading. */
    st_validate_state(st, ST_PIPELINE_RENDER);
    st_flush_bitmap_cache(st);

    if (!st->prefer_blit_based_texture_transfer) {
       goto fallback;
    }

    /* This must be done after state validation. */
    src = strb->texture;

    /* XXX Fallback for depth-stencil formats due to an incomplete
     * stencil blit implementation in some drivers. */
    if (format == GL_DEPTH_STENCIL) {
       goto fallback;
    }

    /* If the base internal format and the texture format don't match, we have
     * to use the slow path. */
    if (rb->_BaseFormat !=
        _mesa_get_format_base_format(rb->Format)) {
       goto fallback;
    }

    if (_mesa_readpixels_needs_slow_path(ctx, format, type, GL_TRUE)) {
       goto fallback;
    }

    /* Convert the source format to what is expected by ReadPixels
     * and see if it's supported. */
    src_format = util_format_linear(src->format);
    src_format = util_format_luminance_to_red(src_format);
    src_format = util_format_intensity_to_red(src_format);

    if (!src_format ||
        !screen->is_format_supported(screen, src_format, src->target,
                                     src->nr_samples,
                                     PIPE_BIND_SAMPLER_VIEW)) {
       goto fallback;
    }

    if (format == GL_DEPTH_COMPONENT || format == GL_DEPTH_STENCIL)
       bind |= PIPE_BIND_DEPTH_STENCIL;
    else
       bind |= PIPE_BIND_RENDER_TARGET;

    /* Choose the destination format by finding the best match
     * for the format+type combo. */
    dst_format = st_choose_matching_format(st, bind, format, type,
                                           pack->SwapBytes);
    if (dst_format == PIPE_FORMAT_NONE) {
       goto fallback;
    }

    if (st->pbo.download_enabled && _mesa_is_bufferobj(pack->BufferObj)) {
       if (try_pbo_readpixels(st, strb,
                              st_fb_orientation(ctx->ReadBuffer) == Y_0_TOP,
                              x, y, width, height,
                              src_format, dst_format,
                              pack, pixels))
          return;
    }

    if (needs_integer_signed_unsigned_conversion(ctx, format, type)) {
       goto fallback;
    }

    /* Cache a staging texture for back-to-back ReadPixels, to avoid CPU-GPU
     * synchronization overhead.
     */
    dst = try_cached_readpixels(st, strb,
                                st_fb_orientation(ctx->ReadBuffer) == Y_0_TOP,
                                width, height, format, src_format, dst_format);
    if (dst) {
       window = false;
    } else {
       /* See if the texture format already matches the format and type,
        * in which case the memcpy-based fast path will likely be used and
        * we don't have to blit. */
       if (_mesa_format_matches_format_and_type(rb->Format, format,
                                                type, pack->SwapBytes, NULL)) {
          goto fallback;
       }

       dst = blit_to_staging(st, strb,
                             st_fb_orientation(ctx->ReadBuffer) == Y_0_TOP,
                             x, y, width, height, format,
                             src_format, dst_format);
       if (!dst)
          goto fallback;

       window = true;
    }

    /* map resources */
    pixels = _mesa_map_pbo_dest(ctx, pack, pixels);

    map = pipe_transfer_map_3d(pipe, dst, 0, PIPE_TRANSFER_READ,
                               0, 0, 0, width, height, 1, &tex_xfer);
    if (!map) {
       _mesa_unmap_pbo_dest(ctx, pack);
       pipe_resource_reference(&dst, NULL);
       goto fallback;
    }

    if (!window)
       map += y * tex_xfer->stride + x * util_format_get_blocksize(dst_format);

    /* memcpy data into a user buffer */
    {
       const uint bytesPerRow = width * util_format_get_blocksize(dst_format);
-      const uint destStride = _mesa_image_row_stride(pack, width, format, type);
+      const int destStride = _mesa_image_row_stride(pack, width, format, type);
       char *dest = _mesa_image_address2d(pack, pixels,
                                          width, height, format,
                                          type, 0, 0);

       if (tex_xfer->stride == bytesPerRow && destStride == bytesPerRow) {
          memcpy(dest, map, bytesPerRow * height);
       } else {
          GLuint row;

          for (row = 0; row < (unsigned) height; row++) {
             memcpy(dest, map, bytesPerRow);
             map += tex_xfer->stride;
             dest += destStride;
          }
       }
    }

    pipe_transfer_unmap(pipe, tex_xfer);
    _mesa_unmap_pbo_dest(ctx, pack);
    pipe_resource_reference(&dst, NULL);
    return;

 fallback:
    _mesa_readpixels(ctx, x, y, width, height, format, type, pack, pixels);
 }



